// 高校受験 数学（展開・因数分解・方程式・比例式・連立方程式など）の単元に動く図解スライドを1つずつ。
// 「なぜ？」の連鎖で、7枚以上。上に図や式の箱、下の帯にそのスライドのひとこと。
import type { DiagramFigure } from './figures';
import { show, bx, lb, ar, ln, ci, pg, band, fresh, C, FILL } from './diagram-kit';

const K: Record<string, [string, string]> = {
  b: [C.blue, FILL.blue],
  g: [C.green, FILL.green],
  r: [C.red, FILL.red],
  m: [C.main, FILL.warm],
  p: [C.purple, FILL.purple],
  y: [C.main, FILL.yellow],
  n: [C.gray, FILL.gray],
};
// 行の書き方: 'b>文字'（1つの箱）／ 'b>左||g>右'（2つ並べる。右の色指定は省略できる）
const rowEls = (rows: string[], y0: number, h: number, gap: number) =>
  rows.flatMap((s, i) => {
    const [c, f] = K[s[0]];
    const t = s.slice(2);
    const y = y0 + i * (h + gap);
    if (t.includes('||')) {
      const [a, b0] = t.split('||');
      const hasK = /^[a-z]>/.test(b0);
      const [c2, f2] = hasK ? K[b0[0]] : [c, f];
      const b = hasK ? b0.slice(2) : b0;
      return [bx(10, y, 148, h, a, c, f, 12), bx(162, y, 148, h, b, c2, f2, 12)];
    }
    return [bx(10, y, 300, h, t, c, f, 12)];
  });
const cap = (t: string, color: string = C.ink) => band(150, lb(160, 190, t, 12, color, 'middle', true));
const S = (note: string, head: string | null, rows: string[], c: string, col?: string) => {
  const h = rows.length >= 4 ? 24 : 28;
  const gap = rows.length >= 4 ? 4 : 6;
  return { note, add: fresh(...(head ? [lb(160, 14, head, 12, C.ink, 'middle', true)] : []), ...rowEls(rows, head ? 28 : 10, h, gap), ...cap(c, col)) };
};

